    def label(
        self, *,
        id: str,
        position: Sequence[int] | None = None,
        span: Sequence[int] | None = None,
        text: _Str | None = None,
        label: _Str | None = None,
        subtitle: _Str | None = None,
        lines: _Num | None = None,
        icon: _Str | None = None,
        style: Literal['default', 'headline', 'title', 'caption', 'mono', 'large-mono', 'terminal'] | None = None,
        glowRadius: _Num | None = None,
        tint: _Str | None = None,
        align: Literal['leading', 'center', 'trailing'] | None = None,
        fontWeight: Literal['ultraLight', 'thin', 'light', 'regular', 'medium', 'semibold', 'bold', 'heavy', 'black'] | None = None,
        forecast: Literal['countdown', 'reach'] | None = None,
        forecastTarget: _Num | None = None,
        forecastTimeFrom: _Str | None = None,
        forecastRate: _Num | None = None,
        unit: _Str | None = None,
        scrollable: _Bool | None = None,
        formatValue: _Str | None = None,
        placeholder: _Str | None = None,
        valueMap: _Obj | None = None,
        iconMap: _Obj | None = None,
        colorMap: _Obj | None = None,
        **props: Any,
    ) -> dict[str, Any]:
        """Text: A line of text, or a value with a caption
        (catalog type `label`)

        Fields:
            text (string): Static display text (overridden by sync). Does: Sets the words on the label; a synced value replaces them as soon as one arrives.
            label (string): Alternative to text. Does: Shows this text when no Text is set at all; an empty Text shows blank, not this. Otherwise the label reads the same either way.
            subtitle (string): A quieter second line under the text (caption size, secondary color). In a list itemTemplate it takes {{item.<field>}}. Does: Adds a compact second line in the caption size and the theme's secondary color; leave it empty for a single line.
            lines (number, default 1): Most lines the text may take (1 = truncate, N = wrap up to N, 0 = wrap freely). Also limits the subtitle. Does: Keeps the text on one line, or lets it wrap onto up to 10 lines; 0 wraps as far as it needs.
            icon (string): SF Symbol before text. Does: Draws the named SF Symbol in front of the text, in the same color and size.
            style (enum, default default): Text style variant (terminal = ANSI terminal renderer). Does: Switches the font between a small line, a headline, a title, a caption and monospaced or terminal looks. Values: default = small body text, headline = bold headline size, title = larger bold title, caption = small caption text, mono = body text in a monospaced font, large-mono = larger monospaced text, good for big numbers, terminal = a dark ANSI terminal view that keeps colors and columns.
            glowRadius (number, default 0): Soft glow behind the text in its own colour, in points (0 = none). Cross-control, same on every control. Does: Adds a blurred glow in the text color, 0 to 30 points wide; 0 turns it off.
            tint (color, default #FFFFFF): Text and icon color. Does: Recolors the text and the symbol in front of it.
            align (enum, default leading): Text alignment. Does: Moves the text to the left edge, the middle or the right edge of the label. Values: leading = text starts at the left edge, center = text is centered, trailing = text ends at the right edge.
            fontWeight (enum, default regular): Font weight laid over the text style. Does: Makes the letters lighter or heavier, from ultra thin to black, on top of the chosen style. Values: ultraLight = hairline strokes, thin = very slim strokes, light = slim strokes, regular = normal strokes, medium = slightly heavier than normal, semibold = firm, between medium and bold, bold = heavy strokes, heavy = very heavy strokes, black = the heaviest strokes.
            forecast (enum): Look ahead beside the real reading: countdown = the value is a time and the widget counts down to it; reach = the value is expected to arrive at forecastTarget (at the time forecastTimeFrom holds) or to keep moving by forecastRate per second. A newer real value always replaces the guess; past its end the value reads stale. Does: Lets the label keep ticking between real readings, marked as about, until a real value replaces it. Values: countdown = the value is a time and the label counts down to it, reach = the value is guessed to move toward a target number until the next real reading.
            forecastTarget (number): The value this one is expected to arrive at (with forecast "reach"). Does: Gives the number the guessed value drifts toward, from -1000000 to 1000000.
            forecastTimeFrom (string): Id of the control whose value is the arrival time (epoch seconds or ISO-8601), for forecast "reach. Does: Uses that control's time value as the moment the guess reaches the target, so the guess lands on time.
            forecastRate (number): Keep moving by this much per second from the last real reading (forecast "reach", no time needed). Does: Moves the displayed number by this much every second after the last real reading, from -1000 to 1000.
            unit (string): Measurement unit the value arrives in ([[values#Units]] name or symbol, e.g. celsius, km/h). A numeric value converts to the device locale; text values show as sent. Unknown strings show literally. Does: Converts a numeric value to the phone's own units, so celsius shows as degrees Fahrenheit in the US; text is shown as sent.
            scrollable (bool, default false): Fixed-height scrolling terminal/log view that keeps the latest line in view (pair with controlHeight). Does: Gives the label a fixed height that scrolls and stays on the newest line.
            formatValue (string): Value display format (see formatValue table; relative / relative:day show a date as time-since). Does: Shows the value as a rounded number, a percent, a duration, a size, a date or a time since, instead of the raw text.
            placeholder (string): Shown by a relative-date label with no date yet (default "Never"). Does: Shows this text (Never by default) on a time-since or date label that has no date yet.
            valueMap (object): Incoming value → display text ("default" catches the rest). Does: Replaces a raw incoming value such as 61 with the words you pick, with default catching the rest.
            iconMap (object): Incoming value → SF Symbol name. Does: Swaps the symbol in front of the text to match the incoming value.
            colorMap (object): Incoming value → hex tint. Does: Recolors the text to match the incoming value, for example green for running.

        Example:
            ui.label('fern-watered', label='Fern — last watered', icon='leaf.fill', formatValue='relative:day', placeholder='Not watered yet', sync=[{'method': 'meshsocket', 'event': 'broadcast', 'filter': {'msg_type': 'fern'}, 'valuePath': 'lastWatered'}])
        """
        return self._ctl("label", dict(id=id, position=position, span=span, text=text, label=label, subtitle=subtitle, lines=lines, icon=icon, style=style, glowRadius=glowRadius, tint=tint, align=align, fontWeight=fontWeight, forecast=forecast, forecastTarget=forecastTarget, forecastTimeFrom=forecastTimeFrom, forecastRate=forecastRate, unit=unit, scrollable=scrollable, formatValue=formatValue, placeholder=placeholder, valueMap=valueMap, iconMap=iconMap, colorMap=colorMap), props)

    def list(
        self, *,
        id: str,
        position: Sequence[int] | None = None,
        span: Sequence[int] | None = None,
        formatValue: _Str | None = None,
        label: _Str | None = None,
        listColumns: _Arr | None = None,
        emptyText: _Str | None = None,
        tint: _Str | None = None,
        hideLabel: _Bool | None = None,
        hideBackground: _Bool | None = None,
        defaultValue: _ObjList | None = None,
        confirm: _Bool | None = None,
        paging: _Obj | None = None,
        pageSize: _Num | None = None,
        request: _Obj | None = None,
        replyType: _Str | None = None,
        replyPath: _Str | None = None,
        window: _Num | None = None,
        queryFrom: _Str | None = None,
        itemTemplate: _Obj | None = None,
        itemSpacing: _Num | None = None,
        itemStyle: Literal['plain', 'card'] | None = None,
        itemLayout: Literal['rows', 'grid'] | None = None,
        **props: Any,
    ) -> dict[str, Any]:
        """Table: Rows of information
        (catalog type `list`)

        Fields:
            formatValue (string): Default date format for columns with no `format` of their own: relative:day (4 days ago), relative, date, date:time. Applies to date text and epoch numbers; other text shows as is. Does: Dates in columns without their own format show as e.g. 4 days ago (relative:day) or a calendar date; other text is unchanged.
            label (string): Header label. Does: Shows this text as the header line above the rows in the header text size.
            listColumns (array): Column definitions: [{key, label, format}]. Absent or empty: a store-bound list shows its collection's first fields, any other list its rows' own keys. Does: Sets the columns across each row: their order, header text and number or date format; with none, up to 3 columns are picked from the data.
            emptyText (string): Line shown when the list has no rows. Default: \\"No <label> yet\\". Does: Replaces the line shown when there are no rows, e.g. No books yet.
            tint (color, default #FFFFFF): Header text color. Does: Paints the header label in this color.
            hideLabel (bool, default false): Hide header label. Does: Removes the header label so the rows start at the top of the card.
            hideBackground (bool, default false): Remove glass card background. Does: Drops the frosted card fill so the rows sit directly on the screen background.
            defaultValue (object[]): Seed rows shown before the first sync (the same row objects a sync delivers). Does: Fills the list with these rows before the first sync, e.g. 3 sample rows, then new data replaces them.
            confirm (bool, default false): After this control's local write lands, show a pill naming the change with an Undo button for 3 seconds (default off). Does: After a tap writes locally, a pill naming the change appears for 3 seconds with an Undo button.
            paging (object): Rows fed by the hub a page at a time: {pageSize, request, replyType, replyPath, window, queryFrom}. Absent: the list shows the rows its sync delivers. See [[#Paging]]. Does: Asks the hub for the first rows when the list appears and for more as you near the end, so a list of any length scrolls without the phone holding every row.
            pageSize (number, default 50): Rows asked for per request, sent as {{limit}} (5-200). A hub may send fewer. Does: Asks the hub for this many rows at a time, e.g. 50; the next request goes out when you are half a page from the last row.
            request (object): The action sent for each page (meshsocket; `method` may be left out), with {{cursor}}, {{offset}}, {{limit}}, {{query}} and {{req}} filled into its payload. See [[#Paging]]. Does: Sends this message for every page with the position, the page size and the search text filled in.
            replyType (string): msg_type of the hub's page broadcasts. A page is {items (or rows), cursor?, total?, more?, offset?, query?, req?}; a frame of this type without items or rows is ignored. Does: Takes rows only from hub messages of this type and leaves every other message alone.
            replyPath (string): Dot path from the reply frame to the page object, e.g. result for {msg_type, req, result: {rows, total}}. Absent: the frame is the page. Does: Reads the page from this part of each reply, e.g. result, instead of from the top of the message.
            window (number, default 600): Most rows kept on the phone at once (at least 4 pages, at most 5000). Rows far from the screen are let go and asked for again when you scroll back. Does: Keeps at most this many rows around the ones on screen, e.g. 600, and asks the hub again for rows you scroll back to.
            queryFrom (string): Id of a text input whose text is the search, sent as {{query}}. A change starts the list over after 250 ms without typing. Does: Sends that field's text as the search with every request, and starts the list over from the top when the text changes.
            itemTemplate (object): A group definition ({grid, children}) drawn once per row; {{item.<field>}} in its children's text, values, images and payloads is replaced from that row. Absent: rows are columns. See [[#Item templates]]. Does: Lays out each row as its own small grid of controls, e.g. a name, a version and a button, filled in from that row's data.
            itemSpacing (number, default 2): Points between rows (0-64, default 2), and between the cards of a card grid (itemLayout: grid). Does: Opens up space between rows, so card-style rows stand apart from each other.
            itemStyle (enum, default plain): plain: rows sit inside the list's card. card: each itemTemplate row draws its template group's own card (fill, corners, theme), so rows read as separate cards; pair it with hideBackground: true and an itemSpacing. See [[#Card rows]]. Does: Gives every templated row a card of its own, styled by the template's theme, instead of lines inside one list card. Values: plain = rows sit inside the list's own card, as before, card = each templated row is its own card, styled by the template group.
            itemLayout (enum, default rows): rows: one templated row per line. grid: the itemTemplate rows as cards side by side, as many columns as keep each card 150 pt wide or more, at most 3 (2 on a phone-wide list, 3 on an iPad or in landscape, 1 on a list too narrow for two), itemSpacing apart; paging, search, row taps and itemStyle work as in rows. Needs an itemTemplate: column rows stay one per line. Any other value is rows. See [[#Card grid]]. Does: Lays the templated rows out as a grid of cards, 2 or 3 to a line by the list's width, scrolling and loading as the rows do. Values: rows = one templated row per line, as before, grid = templated rows as cards side by side, 2 or 3 columns by the list's width.

        Example:
            ui.list('packages', position=[0, 0], span=[6, 4], hideBackground=True, itemStyle='card', itemSpacing=10, itemTemplate={'grid': {'columns': 4, 'rows': 1}, 'children': [{'type': 'image', 'id': 'icon', 'position': [0, 0], 'systemName': 'shippingbox'}, {'type': 'label', 'id': 'name', 'position': [0, 1], 'span': [1, 2], 'text': '{{item.name}} {{item.version}}'}, {'type': 'button', 'id': 'install', 'position': [0, 3], 'label': 'Install', 'action': {'method': 'meshsocket', 'event': 'install', 'payload': {'id': '{{item.id}}'}}}], 'expand': {'title': '{{item.name}}', 'grid': {'columns': 4, 'rows': 5}, 'children': [{'ref': 'icon', 'position': [0, 0], 'span': [2, 2]}, {'ref': 'name', 'position': [0, 2], 'span': [1, 2]}, {'ref': 'install', 'position': [1, 2], 'span': [1, 2]}, {'type': 'label', 'position': [2, 0], 'span': [3, 4], 'text': '{{item.notes}}'}]}}, sync=[{'method': 'meshsocket', 'type': 'listen', 'event': 'broadcast', 'filter': {'msg_type': 'packages'}, 'valuePath': 'items'}])
        """
        return self._ctl("list", dict(id=id, position=position, span=span, formatValue=formatValue, label=label, listColumns=listColumns, emptyText=emptyText, tint=tint, hideLabel=hideLabel, hideBackground=hideBackground, defaultValue=defaultValue, confirm=confirm, paging=paging, pageSize=pageSize, request=request, replyType=replyType, replyPath=replyPath, window=window, queryFrom=queryFrom, itemTemplate=itemTemplate, itemSpacing=itemSpacing, itemStyle=itemStyle, itemLayout=itemLayout), props)

    def log_console(
        self, *,
        id: str,
        position: Sequence[int] | None = None,
        span: Sequence[int] | None = None,
        label: _Str | None = None,
        style: Literal['default', 'transparent'] | None = None,
        maxLines: _Num | None = None,
        showTimestamps: _Bool | None = None,
        fontSize: _Num | None = None,
        autoScroll: _Bool | None = None,
        controlHeight: _Num | None = None,
        logColors: _Obj | None = None,
        tint: _Str | None = None,
        defaultValue: _Arr | None = None,
        **props: Any,
    ) -> dict[str, Any]:
        """Log: Lines of messages as they arrive
        (catalog type `logConsole`)

        Fields:
            label (string): Header label. Does: Shows this text in the header above the console, next to a count of the lines kept.
            style (enum, default default): default (dark bg) or transparent. Does: Picks whether the lines sit on the theme's second background fill or on a clear background. Values: default = the lines sit on a filled panel, transparent = no panel fill, so the card behind shows through.
            maxLines (number, default 200): Maximum buffered lines. Does: Shows only this many of the newest lines; older ones scroll away.
            showTimestamps (bool, default true): Prefix each line with timestamp. Does: Puts the time (hours, minutes, seconds) in front of every line when on.
            fontSize (number, default 11): Monospace font size. Does: Sets the size of the monospace text on every line.
            autoScroll (bool, default true): Auto-scroll to latest line. Does: Keeps the view pinned to the latest line as new ones arrive, until you drag up to read older ones.
            controlHeight (number): Console area height in points (default: compact, capped at 200). Set it when the console should fill a tall grid span. Does: Sets the height of the console area in points; without it the area stays compact at no more than 200.
            logColors (object): Map log levels to colors: {\\"error\\": \\"#FF3B30\\", \\"warn\\": \\"#FF9500\\"}. Does: Colors each line by its level name, for example error or warn, overriding the theme's built-in level colors.
            tint (color, default #FFFFFF): Color of the lines with no level. Does: Colors the lines with no level, or a level no color names; lines with a level keep their level color.
            defaultValue (array): Seed lines shown before the first sync (strings, or objects with text and level). Does: Fills the console with these lines before any synced line arrives.

        Example:
            ui.log_console('app-logs', position=[0, 0], span=[3, 4], label='Application Logs', maxLines=500, showTimestamps=True, fontSize=12, autoScroll=True, logColors={'error': '#FF3B30', 'warn': '#FF9500', 'info': '#34C759', 'debug': '#8E8E93'}, sync=[{'method': 'meshsocket', 'type': 'listen', 'event': 'broadcast', 'filter': {'msg_type': 'log_stream'}}])
        """
        return self._ctl("logConsole", dict(id=id, position=position, span=span, label=label, style=style, maxLines=maxLines, showTimestamps=showTimestamps, fontSize=fontSize, autoScroll=autoScroll, controlHeight=controlHeight, logColors=logColors, tint=tint, defaultValue=defaultValue), props)

    def map(
        self, *,
        id: str,
        position: Sequence[int] | None = None,
        span: Sequence[int] | None = None,
        mapStyle: Literal['standard', 'satellite', 'hybrid', 'globe'] | None = None,
        mapInteractive: _Bool | None = None,
        mapZoom: _Num | None = None,
        label: _Str | None = None,
        tint: _Str | None = None,
        mapConfig: _Obj | None = None,
        markerStyle: Literal['dot', 'symbol', 'puck'] | None = None,
        recenter: Literal['auto', 'always', 'initial', 'off'] | None = None,
        markerSizeProperty: _Str | None = None,
        markerSizeDomain: Any | None = None,
        markerSizeRange: Any | None = None,
        markerColorProperty: _Str | None = None,
        markerLabelProperty: _Str | None = None,
        rippleProperty: _Str | None = None,
        rippleThreshold: _Num | None = None,
        ripple: _Obj | None = None,
        maxMarkers: _Num | None = None,
        center: Any | None = None,
        markersPath: _Str | None = None,
        markerLatProperty: _Str | None = None,
        markerLngProperty: _Str | None = None,
        markerIdProperty: _Str | None = None,
        coordinateOrder: Literal['lnglat', 'latlng'] | None = None,
        minWeight: _Num | None = None,
        markerSymbol: _Str | None = None,
        markerSymbolProperty: _Str | None = None,
        motion: _Bool | None = None,
        motionDuration: _Num | None = None,
        hideLabel: _Bool | None = None,
        controlHeight: _Num | None = None,
        **props: Any,
    ) -> dict[str, Any]:
        """Map: A place on a map
        (catalog type `map`)

        Fields:
            mapStyle (enum, default standard): Map rendering style (globe frames the whole Earth). Does: Draws the map as a street map, satellite photos, photos with labels, or a whole-Earth globe. Values: standard = a normal street map, satellite = satellite photos with no labels, hybrid = satellite photos with street and place labels, globe = the whole Earth seen from space, ignoring Zoom.
            mapInteractive (bool, default true): Allow user pan/zoom. Does: When on you can pan and zoom the map with your fingers; off locks the view.
            mapZoom (number, default 0.01): Default coordinate span in degrees. Does: Sets how much ground a single-point view shows, as a span in degrees; smaller zooms in closer.
            label (string): Header label above the map. Does: Shows this text as a header above the map.
            tint (color, default #667eea): Default marker color (used when a marker carries none). Does: Colors every pin that does not bring its own color.
            mapConfig (object): Property→style mapping for GeoJSON feeds (marker size/color/label/ripple). Does: Tells the map which properties of your data set pin size, color, label and ripple.
            markerStyle (enum, default dot): How each pin is drawn (mapConfig.markerStyle). Does: Draws each pin as a plain dot, a bare SF Symbol (named by mapConfig.markerSymbol), or a symbol inside a filled circle. Values: dot = a plain round dot, symbol = a bare symbol such as an airplane, puck = a symbol inside a filled circle.
            recenter (enum, default auto): How the camera reacts to new data (mapConfig.recenter). Does: Chooses when the camera refits to the pins as new data arrives. Values: auto = frames and follows the pins, but stops once you pan or zoom yourself, always = refits to the pins on every update, initial = frames the pins once and then stays put, off = never moves the camera.
            markerSizeProperty (string): Numeric feed property that drives pin size (mapConfig.markerSizeProperty), scaled from markerSizeDomain into markerSizeRange. Does: Sizes each pin from this number in your data, so bigger readings draw bigger pins.
            markerSizeDomain (number[], default [0, 10]): Input range [low, high] of markerSizeProperty (mapConfig.markerSizeDomain). Does: Treats readings at the low end as the smallest pin and at the high end as the largest.
            markerSizeRange (number[], default [8, 30]): Output pin diameter range [smallest, largest] in points (mapConfig.markerSizeRange). Does: Sets the smallest and largest pin size in points.
            markerColorProperty (string): Feed property holding a hex color for each pin (mapConfig.markerColorProperty). Does: Colors each pin with the hex color found under this name in your data.
            markerLabelProperty (string): Feed property used as each pin's label (mapConfig.markerLabelProperty). Does: Writes this value from your data beside each pin.
            rippleProperty (string): Numeric feed property that decides which pins ripple (mapConfig.rippleProperty). Does: Pulses a ring around every pin whose reading here reaches the ripple threshold.
            rippleThreshold (number, default 0): rippleProperty >= rippleThreshold makes that pin ripple (mapConfig.rippleThreshold). Does: Pulses only the pins whose reading is at least this number.
            ripple (object): Ring styling for rippling pins: color, period (s, default 1.6), radius (pt, default 44) (mapConfig.ripple). Does: Sets the ring's color, how long one pulse takes, and how wide it grows.
            maxMarkers (number, default 400): Cap on drawn pins; a public feed can be unbounded (mapConfig.maxMarkers). Does: Draws at most this many pins, so a huge feed stays smooth.
            center (number[]): Fixed camera centre [lat, lng] instead of fitting the data; combines with recenter (mapConfig.center). Does: Points the map at this latitude and longitude instead of framing the pins.
            markersPath (string): Dot-path to the array of point objects in a non-GeoJSON payload, e.g. "ac" (mapConfig.markersPath). Does: Reads the pins from the list found under this name in your data.
            markerLatProperty (string): Property holding latitude on each point object, e.g. "lat"; switches to object-array mode (mapConfig.markerLatProperty). Does: Places each pin at the latitude found under this name.
            markerLngProperty (string): Property holding longitude on each point object, e.g. "lon" (mapConfig.markerLngProperty). Does: Places each pin at the longitude found under this name.
            markerIdProperty (string): Property giving each pin a stable identity across updates; needed for smooth motion (mapConfig.markerIdProperty). Does: Keeps each pin the same pin across updates, so it glides instead of jumping.
            coordinateOrder (enum, default lnglat): Order of raw [a, b, weight] number triples, GeoJSON-style lnglat or latlng (mapConfig.coordinateOrder). Does: Reads each number pair as longitude then latitude, or latitude then longitude. Values: lnglat = each pair is longitude then latitude, the GeoJSON order, latlng = each pair is latitude then longitude.
            minWeight (number): In number-triple mode, drop points whose weight is below this before capping (mapConfig.minWeight). Does: Leaves out points whose weight is below this number, keeping the strongest ones.
            markerSymbol (string): Default SF Symbol name for the symbol and puck pin styles, e.g. "airplane" (mapConfig.markerSymbol). Does: Draws this symbol for each pin when the pin style is symbol or puck.
            markerSymbolProperty (string): Per-object property naming an SF Symbol, overriding markerSymbol (mapConfig.markerSymbolProperty). Does: Gives each pin the symbol named under this value in your data.
            motion (bool, default false): Glide pins between updates instead of snapping; needs markerIdProperty with more than one pin (mapConfig.motion). Does: Moves each pin smoothly to its new position when fresh data arrives.
            motionDuration (number, default 1.2): Seconds one position glide takes; set near the poll interval (mapConfig.motionDuration). Does: Takes this many seconds to move a pin to its new spot.
            hideLabel (bool, default false): Hide the header label above the map. Does: On hides the title row above the map even when a label is set; off shows it.
            controlHeight (number): Map height in points in a flow-mode grid (2-D grids size it by rowSpan). Does: Sets the map height from 120 to 1200 points when the grid flows; 2-D grids use row span instead.

        Example:
            ui.map('vehicle-location', position=[0, 0], span=[3, 4], mapStyle='standard', mapInteractive=True, mapZoom=0.005, label='Vehicle', tint='#FF3B30', sync=[{'method': 'meshsocket', 'type': 'listen', 'event': 'broadcast', 'filter': {'msg_type': 'gps_update'}, 'valuePath': 'map_data'}])
        """
        return self._ctl("map", dict(id=id, position=position, span=span, mapStyle=mapStyle, mapInteractive=mapInteractive, mapZoom=mapZoom, label=label, tint=tint, mapConfig=mapConfig, markerStyle=markerStyle, recenter=recenter, markerSizeProperty=markerSizeProperty, markerSizeDomain=markerSizeDomain, markerSizeRange=markerSizeRange, markerColorProperty=markerColorProperty, markerLabelProperty=markerLabelProperty, rippleProperty=rippleProperty, rippleThreshold=rippleThreshold, ripple=ripple, maxMarkers=maxMarkers, center=center, markersPath=markersPath, markerLatProperty=markerLatProperty, markerLngProperty=markerLngProperty, markerIdProperty=markerIdProperty, coordinateOrder=coordinateOrder, minWeight=minWeight, markerSymbol=markerSymbol, markerSymbolProperty=markerSymbolProperty, motion=motion, motionDuration=motionDuration, hideLabel=hideLabel, controlHeight=controlHeight), props)

    def picker(
        self, *,
        id: str,
        position: Sequence[int] | None = None,
        span: Sequence[int] | None = None,
        animation: Literal['smooth', 'snappy', 'bouncy', 'gentle', 'instant'] | None = None,
        optionIcons: _Arr | None = None,
        optionLabels: _Arr | None = None,
        placeholder: _Str | None = None,
        options: _Arr | None = None,
        pickerStyle: Literal['menu', 'wheel', 'inline'] | None = None,
        label: _Str | None = None,
        tint: _Str | None = None,
        defaultValue: _Str | None = None,
        haptic: Literal['light', 'medium', 'heavy', 'rigid', 'soft', 'success', 'warning', 'error', 'selection'] | None = None,
        hideLabel: _Bool | None = None,
        hideBackground: _Bool | None = None,
        confirm: _Bool | None = None,
        **props: Any,
    ) -> dict[str, Any]:
        """Menu: Pick one from a list
        (catalog type `picker`)

        Fields:
            animation (enum): Motion profile for value changes. Does: Sets how the shown choice transitions when the value changes, from instant swap to a soft glide. Values: smooth = an even natural transition, snappy = a quick firm change, bouncy = overshoots slightly then settles, gentle = a slow soft change, instant = swaps with no transition.
            optionIcons (array): Optional SF Symbols parallel to options, supported in every picker style. Does: Shows the SF Symbol at the same position next to each choice, in every look; a blank or missing entry shows no icon.
            optionLabels (array): Display labels parallel to options; actions and sync use the original option values. Does: Shows these names instead of the stored values; the original value is still what is saved and sent.
            placeholder (string): Text shown when no options are available or a picker has no selection. Does: Writes this text when the list is empty (default No options) or nothing is selected (default Choose…).
            options (array): Available choices (string array). Does: Fills the menu, wheel or list with one row per entry; the picked entry is the value stored and sent.
            pickerStyle (enum, default menu): Display style. Does: Switches between a compact dropdown, a spinning wheel, or a list shown in full. Values: menu = a compact button that opens a dropdown, wheel = a spinning drum you scroll to a choice, inline = every choice shown as a tappable list.
            label (string): Display label. Does: Writes this text as the picker title.
            tint (color, default #667eea): Accent color. Does: Colors the selected choice and the picker accent with this color.
            defaultValue (string): Initially selected option. Does: Selects this choice when the layout first appears; it should match one of the stored values.
            haptic (enum, default selection): Default haptic on change. Does: Plays this haptic on the phone each time a new choice is picked (default selection). Values: light = a faint tap, medium = a firm tap, heavy = a strong thud, rigid = a firm sharp click, soft = a gentle cushioned tap, success = a happy double tap, warning = a cautionary buzz, error = a sharp triple buzz, selection = a tiny tick like scrolling a wheel.
            hideLabel (bool, default false): Hide the label. Does: Hides the label text above the control.
            hideBackground (bool, default false): Remove glass background. Does: Removes the frosted card behind the control so it sits on the page.
            confirm (bool, default false): After this control's local write lands, show a pill naming the change with an Undo button for 3 seconds (default off). Does: Shows a pill naming the change with an Undo button for 3 seconds after you pick a choice.

        Example:
            ui.picker('drive-mode', position=[0, 0], options=['eco', 'comfort', 'sport'], optionLabels=['Economy', 'Comfort', 'Sport'], optionIcons=['leaf', 'car', 'bolt'], defaultValue='eco')
        """
        return self._ctl("picker", dict(id=id, position=position, span=span, animation=animation, optionIcons=optionIcons, optionLabels=optionLabels, placeholder=placeholder, options=options, pickerStyle=pickerStyle, label=label, tint=tint, defaultValue=defaultValue, haptic=haptic, hideLabel=hideLabel, hideBackground=hideBackground, confirm=confirm), props)

