    def toggle(
        self, *,
        id: str,
        position: Sequence[int] | None = None,
        span: Sequence[int] | None = None,
        animation: Literal['smooth', 'snappy', 'bouncy', 'gentle', 'instant'] | None = None,
        label: _Str | None = None,
        icon: _Str | None = None,
        style: Literal['switch', 'button', 'icon-toggle'] | None = None,
        defaultValue: _Bool | None = None,
        onIcon: _Str | None = None,
        offIcon: _Str | None = None,
        tint: _Str | None = None,
        hideBackground: _Bool | None = None,
        haptic: Literal['light', 'medium', 'heavy', 'rigid', 'success', 'warning', 'error', 'selection'] | None = None,
        trackLength: _Num | None = None,
        trackCurvature: _Num | None = None,
        trackRadius: _Num | None = None,
        knobRadius: _Num | None = None,
        confirm: _Bool | None = None,
        **props: Any,
    ) -> dict[str, Any]:
        """Switch: Turns something on or off
        (catalog type `toggle`)

        Fields:
            animation (enum): Motion profile for value changes. Does: Sets the speed and feel of the knob's travel between off and on, from instant to a slow ease. Values: smooth = an even natural glide, snappy = quick with a crisp stop, bouncy = overshoots slightly and settles, gentle = slow and soft, instant = no travel, it jumps straight to the new state.
            label (string): Toggle label text. Does: Shows this text above the switch in the label font size (8-24 pt, default 12).
            icon (string): SF Symbol. Does: Draws this SF Symbol beside the label; leave it empty for no icon.
            style (enum, default switch): Display style. Does: Switches the whole control between an iOS-style sliding switch, a tappable button and a single icon that swaps. Values: switch = a sliding track with a round knob, button = a tappable tile that glows in the on color when on, icon-toggle = one symbol that swaps between the on and off icons.
            defaultValue (bool, default false): Initial on/off state. Does: Starts the control on (true) or off (false) until the first tap or live update.
            onIcon (string): SF Symbol when on (button and icon-toggle styles). Does: Shows this SF Symbol while the control is on, replacing the main icon in button and icon-toggle looks.
            offIcon (string): SF Symbol when off (button and icon-toggle styles). Does: Shows this SF Symbol while the control is off, replacing the main icon in button and icon-toggle looks.
            tint (color, default #667eea): Accent color when on. Does: Colors the track, glow or icon in this color whenever the control is on.
            hideBackground (bool, default false): Remove glass background. Does: Removes the frosted card behind the control so only the switch and label sit on the page.
            haptic (enum, default rigid): Default haptic on toggle. Does: Plays this haptic on the phone each time the control flips. Values: light = a small soft tap, medium = a medium tap, heavy = a strong thud, rigid = a firm sharp click, success = the double tap of a success, warning = a two-pulse warning, error = a sharp triple buzz of an error, selection = the faint tick of picking an item.
            trackLength (number, default 51): Track extent tip-to-tip along its path (pt). Does: Stretches the track tip to tip along its path from 31 to 400 pt (default 51).
            trackCurvature (number, default 0): Degrees of bend; 0 straight, positive bows up. Clamped to what the length can bend (lengthen the track to curve it more). Does: Bends the track from -180 to 180 degrees; 0 is straight, positive bows up and negative bows down.
            trackRadius (number, default 15.5): Track corner radius; on a curved track resolves to round caps (within 0.5 pt of half thickness) or sharp square ends (below). Does: Rounds the track corners from 0 (square) to 20 pt (fully round at default thickness).
            knobRadius (number, default 13.5): Knob corner radius; 0 is a square knob, which rotates to the track's direction on curved tracks. Knob SIZE is derived from the track (fixed ratio, D45a) and is not a dial. Does: Rounds the knob corners from 0 (square) to 13.5 pt (a circle).
            confirm (bool, default false): After this control's local write lands, show a pill naming the change with an Undo button for 3 seconds (default off). Does: Shows a pill naming the change with an Undo button for 3 seconds after each local write.

        Example:
            ui.toggle('lr-main', position=[0, 0], label='Main Light', defaultValue=True, action={'method': 'meshsocket', 'mode': 'send', 'event': 'route_msg_noreply', 'payload': {'target_name': 'hue-bridge', 'type': 'light', 'payload': {'room': 'living', 'fixture': 'main', 'command': '{{value}}'}}}, sync=[{'method': 'meshsocket', 'type': 'listen', 'event': 'broadcast', 'filter': {'room': 'living', 'fixture': 'main'}, 'valuePath': 'state'}])
        """
        return self._ctl("toggle", dict(id=id, position=position, span=span, animation=animation, label=label, icon=icon, style=style, defaultValue=defaultValue, onIcon=onIcon, offIcon=offIcon, tint=tint, hideBackground=hideBackground, haptic=haptic, trackLength=trackLength, trackCurvature=trackCurvature, trackRadius=trackRadius, knobRadius=knobRadius, confirm=confirm), props)

    def treemap(
        self, *,
        id: str,
        position: Sequence[int] | None = None,
        span: Sequence[int] | None = None,
        haptic: Literal['none', 'light', 'medium', 'heavy', 'soft', 'rigid', 'selection', 'success', 'warning', 'error'] | None = None,
        label: _Str | None = None,
        treemapConfig: _Obj | None = None,
        tint: _Str | None = None,
        formatValue: _Str | None = None,
        cellCornerRadius: _Num | None = None,
        cellGap: _Num | None = None,
        colors: _StrList | None = None,
        drillDown: _Bool | None = None,
        itemAction: _Obj | None = None,
        scrub: _Bool | None = None,
        showLabels: _Bool | None = None,
        showValues: _Bool | None = None,
        **props: Any,
    ) -> dict[str, Any]:
        """Blocks: Sizes compared as blocks
        (catalog type `treemap`)

        Fields:
            haptic (enum): Touch feedback on interaction (supported hardware). Does: Plays this touch feedback when a cell is tapped; leave it empty for a light tap. Values: none = no feedback, light = a gentle tap, medium = a medium tap, heavy = a strong tap, soft = a cushioned tap, rigid = a sharp tap, selection = a tiny tick like scrolling a picker, success = a confirming pattern, warning = a cautioning pattern, error = a sharp error pattern.
            label (string): Header label above the map. Does: Shows this text as the header, which becomes a back button while you are zoomed into a group.
            treemapConfig (object): Full configuration object (see TreemapConfig section). Does: Holds the optional look and behavior settings for the blocks.
            tint (color, default #667eea): First-item color and palette seed. Does: Colors the first block and seeds the colors of the rest.
            formatValue (string): Formatter for item values. Does: Formats the values shown on blocks, for example with a unit after the number.
            cellCornerRadius (number, default 5): Cell corner rounding. Does: Rounds each block's corners from square to 30 points.
            cellGap (number, default 2): Gap between cells. Does: Leaves this many points of gap between neighboring blocks.
            colors (string[]): Item color cycle (per-item color wins). Does: Gives blocks colors from this list in turn; a color set on an item wins.
            drillDown (bool, default true): Tap a parent to zoom into its children. Does: When on, tapping a block with items inside zooms into it; when off, every tap acts as a pick.
            itemAction (object): itemAction. Does: Runs this action when you tap a block with nothing inside, passing its label, value and path.
            scrub (bool, default false): Drag highlights the cell under the finger with a live readout (no drilling/actions until a tap). Does: When on, dragging highlights the block under your finger with a live readout, and only a tap drills in or acts.
            showLabels (bool, default true): Item labels inside cells that have room. Does: Draws each block's name inside it where there is room.
            showValues (bool, default false): Value under the label (taller cells only). Does: Draws each block's value under its name on blocks tall enough to fit.

        Example:
            ui.treemap('storage', position=[0, 0], span=[3, 4], label='Storage', formatValue='suffix: GB', treemapConfig={'showValues': True}, sync=[{'method': 'meshsocket', 'type': 'listen', 'event': 'broadcast', 'filter': {'msg_type': 'disk_usage'}, 'valuePath': 'tree'}])
        """
        return self._ctl("treemap", dict(id=id, position=position, span=span, haptic=haptic, label=label, treemapConfig=treemapConfig, tint=tint, formatValue=formatValue, cellCornerRadius=cellCornerRadius, cellGap=cellGap, colors=colors, drillDown=drillDown, itemAction=itemAction, scrub=scrub, showLabels=showLabels, showValues=showValues), props)

    def web_view(
        self, *,
        id: str,
        position: Sequence[int] | None = None,
        span: Sequence[int] | None = None,
        url: _Str | None = None,
        label: _Str | None = None,
        webInteractive: _Bool | None = None,
        webScrollEnabled: _Bool | None = None,
        webRefreshInterval: _Num | None = None,
        hideLabel: _Bool | None = None,
        hideBackground: _Bool | None = None,
        **props: Any,
    ) -> dict[str, Any]:
        """Web page: A web page inside your app
        (catalog type `webView`)

        Fields:
            url (string): URL to load. Does: Loads this web address inside the control; a missing address shows a globe and "No URL". A live synced value that is a full URL replaces it.
            label (string): Header label. Does: Shows this text above the page in the label font size (8-24 pt, default 12); with no label no header row appears.
            webInteractive (bool, default true): Allow user interaction. Does: When off, touches pass through the page so it is display only; when on, links and forms work.
            webScrollEnabled (bool, default true): Allow scrolling. Does: When off, the page stays at its top position and cannot be dragged; when on, you can scroll it.
            webRefreshInterval (number): Auto-refresh interval in seconds. Does: Reloads the page every this many seconds (1 to 3600) while it is on screen; leave it unset for no automatic reload.
            hideLabel (bool, default false): Hide the header label. Does: On hides the title row above the page even when a label is set; off shows it.
            hideBackground (bool, default false): Remove glass card background. Does: Removes the glass card, fill and border so only the page sits on the layout.

        Example:
            ui.web_view('grafana', position=[0, 0], span=[4, 4], label='Metrics Dashboard', url='https://grafana.local/d/overview?kiosk', webInteractive=True, webScrollEnabled=False, webRefreshInterval=30)
        """
        return self._ctl("webView", dict(id=id, position=position, span=span, url=url, label=label, webInteractive=webInteractive, webScrollEnabled=webScrollEnabled, webRefreshInterval=webRefreshInterval, hideLabel=hideLabel, hideBackground=hideBackground), props)
